const candidates = $('Query Candidates Table').all() || [];
const documents = $('Query Documents Table').all() || [];
const requests = $('Query Requests Table').all() || [];

const newApps = candidates.filter(c => c.json.stage === 'Applied').length;
const underReview = candidates.filter(c => c.json.stage === 'Under Review').length;
const interviews = candidates.filter(c => c.json.stage === 'Interview').length;
const onboardingBlockers = documents.filter(d => d.json.review_status === 'Needs Review' || d.json.review_status === 'Missing').length;
const pendingCerts = requests.filter(r => r.json.status === 'Pending').length;
const failedReqs = requests.filter(r => r.json.status?.includes('Failed')).length;

return {
  summary_date: new Date().toISOString().split('T')[0],
  metrics: {
    new_applications: newApps,
    candidates_under_review: underReview,
    interviews_pending: interviews,
    onboarding_blockers: onboardingBlockers,
    certificates_pending_approval: pendingCerts,
    failed_requests: failedReqs
  },
  status: 'AUDIT_COMPLETE'
};

