const requests = $('Query Requests Table').all() || [];
const transientFailures = requests.filter(r => r.json.status === 'Transient_Failure_Eligible_Retry');

return transientFailures.map(r => ({
  request_id: r.json.request_id,
  retry_count: (r.json.retry_count || 0) + 1,
  max_retries: 3,
  action: 'TRIGGER_RETRY'
}));
